static void require(bool ok,const char *message) { if(!ok)throw std::runtime_error(message); }
static void events() { QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QApplication::processEvents(); }
static QByteArray read(const QString &path) { QFile f(path);require(f.open(QIODevice::ReadOnly),"Plot field artifact absent");return f.readAll(); }
static void write(const QString &path,const QByteArray &bytes) { QFile f(path);require(f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size(),"Plot field artifact write failed"); }
static void reveal(QWidget *widget) {
 require(widget,"Plot field widget absent");
 for(auto *p=widget->parentWidget();p;p=p->parentWidget())if(auto *scroll=qobject_cast<QScrollArea *>(p))scroll->ensureWidgetVisible(widget,8,8);
 events();require(widget->isVisible()&&widget->isEnabled(),"Plot field widget unavailable");acceptanceView(*widget);
}
static void paste(QLineEdit *field,const QString &value) {
 reveal(field);QTest::mouseClick(field,Qt::LeftButton);QTest::keyClick(field,Qt::Key_A,Qt::ControlModifier);
 QApplication::clipboard()->setText(value);QTest::keyClick(field,Qt::Key_V,Qt::ControlModifier);events();require(field->text()==value,"Plot field paste altered input");
}
static PlotCommand *probe() {
 QSet<GmatCommand *> seen;
 for(auto *c=Moderator::Instance()->GetFirstCommand();c&&!seen.contains(c);c=c->GmatCommand::GetNext()){
  seen.insert(c);if(missionCommandLabel(QString::fromStdString(c->GetGeneratingString(Gmat::NO_COMMENTS))).name=="Probe")return dynamic_cast<PlotCommand *>(c);
 }
 return nullptr;
}
static QStringList references() {
 auto *c=probe();require(c,"Plot field native command absent");QStringList names;
 for(const auto &name:c->GetRefObjectNameArray(Gmat::SUBSCRIBER))names.append(QString::fromStdString(name));return names;
}
static QJsonObject model(const PlotModel &m) {
 QJsonArray curves;
 for(auto it=m.curves.cbegin();it!=m.curves.cend();++it){QJsonArray points;for(const auto &p:it->points)points.append(QJsonArray{p.x,p.y,p.z,p.epoch,double(p.frame),p.connect,p.highlighted});curves.append(QJsonObject{{"name",it->name},{"points",points}});}
 return QJsonObject{{"kind",int(m.kind)},{"pen_down",m.penDown},{"active",m.active},{"curves",curves}};
}
